      "url": "https://mcp.notion.com/mcp"
    }
  },
  "hooks": {
    "SessionStart": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "export FND_HOST=claude; \"${CLAUDE_PLUGIN_ROOT}/hooks/session-start.sh\" || true"
          }
        ]
      }
    ],
    "UserPromptSubmit": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "export FND_HOST=claude; [ \"${FND_CTX_MONITOR:-1}\" = \"0\" ] && [ \"${FND_PROMPT_JSON:-1}\" = \"0\" ] && [ \"${FND_SESSION_TITLE:-1}\" = \"0\" ] && [ \"${FND_READER_COMPRESSION:-1}\" = \"0\" ] || node \"${CLAUDE_PLUGIN_ROOT}/hooks/user-prompt.cjs\" || true"
          }
        ]
      }
    ],
    "SubagentStart": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "export FND_HOST=claude; \"${CLAUDE_PLUGIN_ROOT}/hooks/subagent-conventions.sh\""
          }
        ]
      }
    ],
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "export FND_HOST=claude; \"${CLAUDE_PLUGIN_ROOT}/hooks/no-ai-attribution.sh\""
          },
          {
            "type": "command",
            "command": "export FND_HOST=claude; \"${CLAUDE_PLUGIN_ROOT}/hooks/no-verify-bypass.sh\""
          }
        ]
      },
      {
        "matcher": "^mcp__.*__(take_screenshot|browser_take_screenshot|take_snapshot|get_network_request|browser_run_code_unsafe)$",
        "hooks": [
          {
            "type": "command",
            "command": "export FND_HOST=claude; [ \"${FND_SCRATCH_GUARD:-1}\" = \"0\" ] || node \"${CLAUDE_PLUGIN_ROOT}/hooks/scratch-path-guard.cjs\" || true"
          }
        ]
      },
      {
        "matcher": "^(Bash|Read|Grep)$",
        "hooks": [
          {
            "type": "command",
            "command": "export FND_HOST=claude; [ \"${FND_SPILL_ACCESS:-1}\" = \"0\" ] || \"${CLAUDE_PLUGIN_ROOT}/hooks/spill-access.sh\" || true"
          }
        ]
      }
    ],
    "PostToolUse": [
      {
        "matcher": "mcp__.*",
        "hooks": [
          {
            "type": "command",
            "command": "export FND_HOST=claude; [ \"${FND_MCP_SLIM:-1}\" = \"0\" ] || [ \"${FND_COMPRESSION:-builtin}\" = \"proxy\" ] || node \"${CLAUDE_PLUGIN_ROOT}/hooks/mcp-slim.cjs\" || true"
          }
        ]
      },
      {
        "matcher": "^(Agent|Task)$",
        "hooks": [
          {
            "type": "command",
            "command": "export FND_HOST=claude; [ \"${FND_READER_COMPRESSION:-1}\" = \"0\" ] || node \"${CLAUDE_PLUGIN_ROOT}/hooks/reader-compression.cjs\" || true"
          }
        ]
      }
    ]
  },
  "types": "./types/index.d.ts",
  "userConfig": {
    "statusBand": {
      "type": "boolean",
      "title": "Status band",
      "description": "Draw fnd's status band above the prompt (Claude Code only); ignored while the band plugin is installed (use band → Hide the status band)",
      "default": true
    },
    "cacheTtl": {
      "type": "string",
      "title": "Prompt cache TTL",
      "description": "auto = learned from the session, else 5m; 5m or 1h forces it; ignored while the band plugin is installed (band has its own)",
      "options": [
        "auto",
        "5m",
        "1h"
      ],
      "default": "auto"
    }
  }
}

